import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.nio.charset.StandardCharsets;

public class ChatServer {
    private static final int MAX_POOL_SIZE = 1024;
    private static final int HEADER_SIZE = 8;
    private static final int MAX_MESSAGE_SIZE = 65536;

    private final ConcurrentHashMap<Integer, ClientConnection> connectionPool;
    private final AtomicInteger connectionCounter;
    private final ExecutorService executor;
    private final ServerSocket serverSocket;
    private final byte[] sharedBuffer;

    public ChatServer(int port) throws IOException {
        this.connectionPool = new ConcurrentHashMap<>();
        this.connectionCounter = new AtomicInteger(0);
        this.executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        this.serverSocket = new ServerSocket(port);
        this.sharedBuffer = new byte[MAX_MESSAGE_SIZE];
    }

    public void start() {
        System.out.println("Chat server started on port " + serverSocket.getLocalPort());
        while (!serverSocket.isClosed()) {
            try {
                Socket client = serverSocket.accept();
                int connId = connectionCounter.incrementAndGet();
                if (connectionPool.size() >= MAX_POOL_SIZE) {
                    client.close();
                    continue;
                }
                ClientConnection conn = new ClientConnection(connId, client);
                connectionPool.put(connId, conn);
                executor.submit(() -> handleClient(conn));
            } catch (IOException e) {
                System.err.println("Accept error: " + e.getMessage());
            }
        }
    }

    private void handleClient(ClientConnection conn) {
        try (InputStream in = conn.socket.getInputStream()) {
            while (!conn.socket.isClosed()) {
                MessageFrame frame = readFrame(in);
                if (frame == null) break;
                processMessage(conn, frame);
            }
        } catch (IOException e) {
            System.err.println("Client " + conn.id + " disconnected: " + e.getMessage());
        } finally {
            connectionPool.remove(conn.id);
            try { conn.socket.close(); } catch (IOException ignored) {}
        }
    }

    private MessageFrame readFrame(InputStream in) throws IOException {
        byte[] header = new byte[HEADER_SIZE];
        int bytesRead = readFully(in, header, 0, HEADER_SIZE);
        if (bytesRead < HEADER_SIZE) return null;

        int messageType = extractInt(header, 0);
        int payloadLength = extractInt(header, 4);

        // Validate payload length before any arithmetic
        if (payloadLength < 0 || payloadLength > MAX_MESSAGE_SIZE) {
            throw new IOException("Invalid payload length: " + payloadLength);
        }

        // Compute total allocation using long to prevent overflow
        long totalSizeLong = computeBufferSizeSafe(messageType, payloadLength);

        if (totalSizeLong < 0 || totalSizeLong > MAX_MESSAGE_SIZE) {
            throw new IOException("Invalid frame size: " + totalSizeLong);
        }

        int totalSize = (int) totalSizeLong;

        byte[] payload = new byte[totalSize];
        bytesRead = readFully(in, payload, 0, payloadLength);
        if (bytesRead < payloadLength) return null;

        return new MessageFrame(messageType, payload, payloadLength);
    }

    /**
     * Computes required buffer size based on message type using long arithmetic
     * to prevent integer overflow.
     * Type 1 (TEXT): payload + 4 bytes for timestamp prefix
     * Type 2 (BINARY): payload + 8 bytes for checksum + sequence
     * Type 3 (BROADCAST): payload + recipient routing space (capped)
     */
    private long computeBufferSizeSafe(int messageType, int payloadLength) {
        long payload = (long) payloadLength;
        switch (messageType) {
            case 1: return payload + 4L;
            case 2: return payload + 8L;
            case 3:
                // Broadcast messages need space for recipient routing table
                // Cap recipient space to prevent excessive allocation
                long recipientSpace = Math.min((long) connectionPool.size() * 4L, 4096L);
                return payload + recipientSpace;
            default: return payload;
        }
    }

    private void processMessage(ClientConnection sender, MessageFrame frame) {
        switch (frame.type) {
            case 1: handleTextMessage(sender, frame); break;
            case 2: handleBinaryMessage(sender, frame); break;
            case 3: handleBroadcast(sender, frame); break;
            default: break;
        }
    }

    private void handleTextMessage(ClientConnection sender, MessageFrame frame) {
        String text = new String(frame.data, 0, frame.actualLength, StandardCharsets.UTF_8);
        String formatted = String.format("[%d] %s", sender.id, text);
        byte[] outBytes = formatted.getBytes(StandardCharsets.UTF_8);

        // Send to all other connected clients
        for (ClientConnection conn : connectionPool.values()) {
            if (conn.id != sender.id) {
                sendToClient(conn, 1, outBytes);
            }
        }
    }

    private void handleBinaryMessage(ClientConnection sender, MessageFrame frame) {
        // Validate checksum in the extra 8 bytes allocated
        if (frame.data.length >= frame.actualLength + 8) {
            long checksum = computeChecksum(frame.data, frame.actualLength);
            byte[] response = new byte[8];
            putLong(response, 0, checksum);
            sendToClient(sender, 2, response);
        }
    }

    private void handleBroadcast(ClientConnection sender, MessageFrame frame) {
        // Broadcast with routing metadata
        int numRecipients = connectionPool.size();
        long metadataSizeLong = (long) numRecipients * 4L;
        if (metadataSizeLong > 4096L) metadataSizeLong = 4096L;
        int metadataSize = (int) metadataSizeLong;

        long totalOutLong = (long) frame.actualLength + metadataSizeLong;
        if (totalOutLong > MAX_MESSAGE_SIZE || totalOutLong < 0) return;
        int totalOut = (int) totalOutLong;

        // Allocate output buffer with routing table
        byte[] outBuffer = new byte[totalOut];
        System.arraycopy(frame.data, 0, outBuffer, 0, frame.actualLength);

        int offset = frame.actualLength;
        for (Map.Entry<Integer, ClientConnection> entry : connectionPool.entrySet()) {
            if (offset + 4 <= outBuffer.length) {
                putInt(outBuffer, offset, entry.getKey());
                offset += 4;
            }
        }

        for (ClientConnection conn : connectionPool.values()) {
            if (conn.id != sender.id) {
                sendToClient(conn, 3, outBuffer);
            }
        }
    }

    private synchronized void sendToClient(ClientConnection conn, int type, byte[] data) {
        try {
            OutputStream out = conn.socket.getOutputStream();
            byte[] header = new byte[HEADER_SIZE];
            putInt(header, 0, type);
            putInt(header, 4, data.length);
            out.write(header);
            out.write(data);
            out.flush();
        } catch (IOException e) {
            connectionPool.remove(conn.id);
        }
    }

    private int readFully(InputStream in, byte[] buf, int off, int len) throws IOException {
        int total = 0;
        while (total < len) {
            int n = in.read(buf, off + total, len - total);
            if (n < 0) return total;
            total += n;
        }
        return total;
    }

    private int extractInt(byte[] buf, int offset) {
        return ((buf[offset] & 0xFF) << 24) |
               ((buf[offset + 1] & 0xFF) << 16) |
               ((buf[offset + 2] & 0xFF) << 8) |
               (buf[offset + 3] & 0xFF);
    }

    private void putInt(byte[] buf, int offset, int value) {
        buf[offset] = (byte) (value >> 24);
        buf[offset + 1] = (byte) (value >> 16);
        buf[offset + 2] = (byte) (value >> 8);
        buf[offset + 3] = (byte) value;
    }

    private void putLong(byte[] buf, int offset, long value) {
        for (int i = 7; i >= 0; i--) {
            buf[offset + i] = (byte) (value & 0xFF);
            value >>= 8;
        }
    }

    private long computeChecksum(byte[] data, int length) {
        long sum = 0;
        for (int i = 0; i < length; i++) {
            sum = (sum * 31 + (data[i] & 0xFF)) & 0xFFFFFFFFFFFFL;
        }
        return sum;
    }

    static class ClientConnection {
        final int id;
        final Socket socket;
        final long connectedAt;

        ClientConnection(int id, Socket socket) {
            this.id = id;
            this.socket = socket;
            this.connectedAt = System.currentTimeMillis();
        }
    }

    static class MessageFrame {
        final int type;
        final byte[] data;
        final int actualLength;

        MessageFrame(int type, byte[] data, int actualLength) {
            this.type = type;
            this.data = data;
            this.actualLength = actualLength;
        }
    }

    public static void main(String[] args) throws IOException {
        int port = args.length > 0 ? Integer.parseInt(args[0]) : 8080;
        new ChatServer(port).start();
    }
}
